namespace ks{namespace{PanelActionPartialTest partialTest=nullptr;using T=PanelActionTask;using S=T::Stage;using K=T::Kind;struct Point{unsigned location,length;};Point point(const T&t){switch(t.kind()){case K::Command:switch(t.stage()){case S::Hold:return{0x8fc,2};case S::Poll:return{0x8fe,2};case S::AwaitPoll:return{0x900,2};case S::Restore:return{0x900,2};case S::CommandByte:return{0x902,4};case S::AwaitCommandByte:return{0x906,2};case S::Finish:return{0x906,2};default:break;}break;case K::ReadData:switch(t.stage()){case S::Poll:return{0x908,2};case S::AwaitPoll:return{0x90a,2};case S::DataRead:return{0x90a,2};case S::AwaitDataRead:return{0x90c,2};case S::Finish:return{0x90c,2};default:break;}break;case K::WriteData:switch(t.stage()){case S::Hold:return{0x90e,2};case S::Poll:return{0x910,2};case S::AwaitPoll:return{0x912,2};case S::CompareReply:return{0x912,2};case S::AdmitReply:return{0x914,2};case S::SetAddress:return{0x916,2};case S::CommandByte:return{0x918,4};case S::AwaitCommandByte:return{0x91c,2};case S::PollAgain:return{0x91c,2};case S::AwaitPollAgain:return{0x91e,2};case S::Restore:return{0x91e,2};case S::DataByte:return{0x920,4};case S::AwaitDataByte:return{0x924,2};case S::Finish:return{0x924,2};default:break;}break;case K::Initialize:switch(t.stage()){case S::SetInitial:return{0x926,2};case S::CommandFirst:return{0x928,2};case S::AwaitCommandFirst:return{0x92a,2};case S::SetDisplay:return{0x92a,2};case S::CommandSecond:return{0x92c,2};case S::AwaitCommandSecond:return{0x92e,2};case S::SetClear:return{0x92e,2};case S::CommandThird:return{0x930,2};case S::AwaitCommandThird:return{0x932,2};case S::Finish:return{0x932,2};default:break;}break;case K::Cursor:switch(t.stage()){case S::AddCursor:return{0x934,2};case S::CommandAction:return{0x936,2};case S::AwaitCommandAction:return{0x938,2};case S::Finish:return{0x938,2};default:break;}break;case K::Spaces:switch(t.stage()){case S::SetSpace:return{0x93a,2};case S::WriteAction:return{0x93c,2};case S::AwaitWriteAction:return{0x93e,2};case S::Decrement:return{0x93e,2};case S::AdmitMore:return{0x940,2};case S::Finish:return{0x942,2};default:break;}break;case K::ClearFirst:switch(t.stage()){case S::SetLine:return{0x944,2};case S::CursorFirst:return{0x946,2};case S::AwaitCursorFirst:return{0x948,2};case S::SetCount:return{0x948,2};case S::SpacesAction:return{0x94a,2};case S::AwaitSpacesAction:return{0x94c,2};case S::SetEnd:return{0x94c,2};case S::CursorLast:return{0x94e,2};case S::AwaitCursorLast:return{0x950,2};case S::Finish:return{0x950,2};default:break;}break;case K::ClearSecond:switch(t.stage()){case S::SetLine:return{0x952,2};case S::CursorFirst:return{0x954,2};case S::AwaitCursorFirst:return{0x956,2};case S::SetCount:return{0x956,2};case S::SpacesAction:return{0x958,2};case S::AwaitSpacesAction:return{0x95a,2};case S::SetEnd:return{0x95a,2};case S::CursorLast:return{0x95c,2};case S::AwaitCursorLast:return{0x95e,2};case S::Finish:return{0x95e,2};default:break;}break;case K::CursorSecond:switch(t.stage()){case S::AddSecond:return{0x960,2};case S::CommandAction:return{0x962,4};case S::AwaitCommandAction:return{0x966,2};case S::Finish:return{0x966,2};default:break;}break;case K::DirectData:switch(t.stage()){case S::Hold:return{0x968,2};case S::Poll:return{0x96a,4};case S::AwaitPoll:return{0x96e,2};case S::Restore:return{0x96e,2};case S::DataByte:return{0x970,4};case S::AwaitDataByte:return{0x974,2};case S::Finish:return{0x974,2};default:break;}break;} throw std::runtime_error("Invalid panel action stage");}std::optional<K>root(unsigned pc){switch(pc){case 0x8fc:return K::Command;case 0x908:return K::ReadData;case 0x90e:return K::WriteData;case 0x926:return K::Initialize;case 0x934:return K::Cursor;case 0x93a:return K::Spaces;case 0x944:return K::ClearFirst;case 0x952:return K::ClearSecond;case 0x960:return K::CursorSecond;case 0x968:return K::DirectData;default:return std::nullopt;}}}
bool PanelActionCalls::step(ControllerCpu&h){using namespace controllerDetail;unsigned pc=unsigned(h.getPC());std::optional<Call>*selected=nullptr;for(auto&c:calls)if(c&&c->token-c->depth==h.getSP()){selected=&c;break;}if(auto kind=root(pc);kind&&!selected){for(auto&c:calls)if(!c){selected=&c;break;}if(!selected)throw std::runtime_error("Panel action capacity");selected->emplace(*kind,h.getSP());++started;}if(!selected||point((**selected).task).location!=pc){if(partialTest&&partialTest(h)){++partialEntries;return true;}return false;}auto&t=(**selected).task;auto&v=h.regs;if(t.child()!=T::Child::None)t.resumeChild(uint8_t(v[6].rl));auto stage=t.stage();auto before=h.cycles;Boundary f(h,pc,point(t).length);auto cost=t.nextClocks();t.advanceBefore(cost,[&](T::Read r){return r==T::Read::Input?uint8_t(v[6].rl):uint8_t(v[6].rh);});switch(stage){case S::Hold:f.push(v[6].r);(**selected).depth+=2;break;case S::Restore:f.pop(v[6].r);(**selected).depth-=2;break;case S::CompareReply:h.sub8(v[6].rl,0x14);break;case S::SetAddress:case S::SetInitial:case S::SetDisplay:case S::SetClear:case S::SetSpace:case S::SetLine:case S::SetEnd:f.move(v[6].rl,t.input());break;case S::SetCount:f.move(v[6].rh,20);break;case S::AddCursor:v[6].rl=h.add8(v[6].rl,0xffffff80);break;case S::AddSecond:v[6].rl=h.add8(v[6].rl,0x40);break;case S::Decrement:f.inc(v[6].rh,-1);break;case S::Poll:f.call(0x8ea);h.pc=h.makepc(f.next);break;case S::PollAgain:f.call(0x8ea);h.pc=h.makepc(f.next);break;case S::CommandByte:f.call(0x862);h.pc=h.makepc(f.next);break;case S::DataByte:f.call(0x8a6);h.pc=h.makepc(f.next);break;case S::DataRead:f.call(0x8c2);h.pc=h.makepc(f.next);break;case S::CommandFirst:f.call(0x8fc);h.pc=h.makepc(f.next);break;case S::CommandSecond:f.call(0x8fc);h.pc=h.makepc(f.next);break;case S::CommandThird:f.call(0x8fc);h.pc=h.makepc(f.next);break;case S::CommandAction:f.call(0x8fc);h.pc=h.makepc(f.next);break;case S::WriteAction:f.call(0x90e);h.pc=h.makepc(f.next);break;case S::CursorFirst:f.call(0x934);h.pc=h.makepc(f.next);break;case S::CursorLast:f.call(0x934);h.pc=h.makepc(f.next);break;case S::SpacesAction:f.call(0x93a);h.pc=h.makepc(f.next);break; case S::Finish:f.ret();h.pc=h.makepc(f.next);selected->reset();++completed;break;default:break;}if(stage!=S::Finish&&t.child()==T::Child::None)h.pc=h.makepc(point(t).location);if(h.cycles-before!=cost)throw std::runtime_error("Panel action clocks differ");return true;}}

